```tsx
import { useEffect, useState } from "react";
import "./StatusMessage.css";

export interface StatusMessageProps {
  text: string;
  onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps) {
  // Screen readers reliably announce changes to a live region that already
  // exists, so the text is written in after mount rather than rendered on the
  // first pass with the region.
  const [announced, setAnnounced] = useState("");

  useEffect(() => {
    setAnnounced(text);
  }, [text]);

  // Escape dismisses the message from anywhere on the page, so keyboard-only
  // users never have to tab to the button to clear it.
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onDismiss();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [onDismiss]);

  return (
    <div className="status-message" role="status" aria-live="polite" aria-atomic="true">
      <p className="status-message__text">{announced}</p>
      <button type="button" className="status-message__dismiss" onClick={onDismiss}>
        Dismiss
      </button>
    </div>
  );
}
