  --sm-focus: #4a6fa5;
  --sm-shadow: 0 4px 14px rgba(46, 42, 36, 0.12);
}

/* Night theme: applied when an ancestor (or the element itself) carries data-theme="night" */
[data-theme="night"] .status-message,
.status-message[data-theme="night"] {
  --sm-bg: #1f2328;
  --sm-border: #3a4048;
  --sm-text: #e6e2da;
  --sm-muted: #a9a399;
  --sm-button-bg: #2b3038;
  --sm-button-hover: #353b44;
  --sm-focus: #8fb3e0;
  --sm-shadow: 0 4px 18px rgba(0, 0, 0, 0.45);
}

.status-message {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  box-sizing: border-box;
  width: 100%;
  max-width: 32rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--sm-border);
  border-radius: 0.5rem;
  background: var(--sm-bg);
  color: var(--sm-text);
  box-shadow: var(--sm-shadow);
  font-family: inherit;
  animation: status-message-in 220ms ease-out both;
}

.status-message__text {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.4;
  color: var(--sm-text);
  overflow-wrap: anywhere;
}

.status-message__dismiss {
  flex-shrink: 0;
  padding: 0.35rem 0.75rem;
  border: 1px solid var(--sm-border);
  border-radius: 0.375rem;
  background: var(--sm-button-bg);
  color: var(--sm-muted);
  font: inherit;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background-color 120ms ease, color 120ms ease;
}

.status-message__dismiss:hover {
  background: var(--sm-button-hover);
  color: var(--sm-text);
}

.status-message__dismiss:focus-visible {
  outline: 2px solid var(--sm-focus);
  outline-offset: 2px;
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .status-message {
    animation: none;
  }

  .status-message__dismiss {
    transition: none;
  }
}
